node -e "
import('node:fs').then(fs => {
  const base = fs.realpathSync('node_modules/@re-cinq/eslint-plugin-re-lint');
  console.log('base:', base);
  for (const f of fs.readdirSync(base + '/rules').filter(x => x.includes('test') || x.includes('spec') || x.includes('colocated') || x.includes('expect'))) {
    console.log('=== ' + f + ' ===');
    console.log(fs.readFileSync(base + '/rules/' + f, 'utf8'));
  }
});
"

node -e "
import('node:fs').then(fs => {
  const base = 'node_modules/@re-cinq/eslint-plugin-re-lint';
  const walk = d => fs.readdirSync(d, {withFileTypes: true}).flatMap(e => e.isDirectory() ? walk(d + '/' + e.name) : [d + '/' + e.name]);
  const files = walk(base).filter(x => x.includes('test') || x.includes('spec') || x.includes('colocated') || x.includes('expect'));
  for (const f of files.filter(x => x.endsWith('.js'))) {
    console.log('=== ' + f + ' ===');
    console.log(fs.readFileSync(f, 'utf8'));
  }
});
"

